const { items, activeIndex, activeSize, captureLayout } = makeSortableList(scrollRef, {
  id: props.column.id,
  items: props.column.cards, // a shallowRef per column
  group: 'board',
});

const virtualizer = useVirtualizer(
  computed(() => {
    const arr = items.value;
    const pin = activeIndex.value;
    const size = activeSize.value;
    return {
      count: arr.length,
      getScrollElement: () => scrollRef.value,
      // A card coming from another column gets its real height before it is measured.
      estimateSize: (index: number) => (index === pin && size ? size.height + GAP : 72),
      // …getItemKey, rangeExtractor and onChange as above
    };
  }),
);

export interface Task {
  id: string;
  title: string;
  owner: string;
}

const TITLES = [
  'Review the release notes',
  'Fix the flaky drag test',
  'Write the migration guide',
  'Measure auto-scroll speed',
  'Design the empty state',
  'Ship keyboard drags',
  'Plan the next sprint',
  'Profile 10,000 rows',
  'Answer the open issues',
  'Record the demo video',
  'Test on a real phone',
  'Polish the overlay',
];
const OWNERS = ['AL', 'MK', 'JS', 'RP', 'TN'];

/** `count` tasks, the same every time. */
export const makeTasks = (count: number): Task[] =>
  Array.from({ length: count }, (_, i) => ({
    id: `t${i + 1}`,
    title: TITLES[i % TITLES.length]!,
    owner: OWNERS[(i * 3) % OWNERS.length]!,
  }));

export interface Note {
  id: string;
  title: string;
  body: string;
  tag: 'Idea' | 'Bug' | 'Todo' | 'Read';
}

const TITLES = [
  'Pinch to zoom on the board',
  'Overlay flickers on Safari',
  'Write the release post',
  'Read: FLIP animations',
  'Undo for every drop',
  'Dark mode for the editor',
  'Keyboard drags in tables',
  'Card covers from links',
];
const SENTENCES = [
  'Short and sweet.',
  'Came up twice in the last call, worth a closer look before Friday.',
  'Needs a quick design pass and a test on a real phone, then it can ship with the next minor.',
  'Ask the team.',
  'Links, screenshots and the whole thread are in the issue; the fix may be a one-liner, or it may not.',
];
const TAGS: Note['tag'][] = ['Idea', 'Bug', 'Todo', 'Read'];

/** `count` notes, the same every time, with bodies of one to three sentences. */
export const makeNotes = (count: number): Note[] =>
  Array.from({ length: count }, (_, i) => ({
    id: `n${i + 1}`,
    title: TITLES[i % TITLES.length]!,
    body: Array.from({ length: 1 + ((i * 7) % 3) }, (_, s) => SENTENCES[(i + s * 3) % SENTENCES.length]).join(' '),
    tag: TAGS[(i * 5) % TAGS.length]!,
  }));

import { shallowRef, type ShallowRef } from 'vue';

export interface Card {
  id: string;
  title: string;
  /** Every third card has a note: the cards differ in height. */
  note?: string;
  points: number;
}

export interface Column {
  id: string;
  title: string;
  color: string;
  /** A shallowRef per column: its list writes the drops into it, and 1,000 cards get no deep proxies. */
  cards: ShallowRef<Card[]>;
}

const TITLES = ['Sync the calendar', 'Fix the login redirect', 'Export to CSV', 'Onboarding emails', 'Search by tag', 'Retry failed uploads'];
const NOTES = ['Blocked by the API review', 'Needs a design pass', 'Customer request'];

const makeCards = (prefix: string, count: number, shift: number): Card[] =>
  Array.from({ length: count }, (_, i) => ({
    id: `${prefix}-${i + 1}`,
    title: TITLES[(i + shift) % TITLES.length]!,
    note: i % 3 === 1 ? NOTES[(i + shift) % NOTES.length] : undefined,
    points: [1, 2, 3, 5, 8][(i + shift) % 5]!,
  }));

export const makeColumns = (perColumn: number): Column[] => [
  { id: 'todo', title: 'To do', color: '#3b82f6', cards: shallowRef(makeCards('TD', perColumn, 0)) },
  { id: 'doing', title: 'In progress', color: '#f59e0b', cards: shallowRef(makeCards('IP', perColumn, 2)) },
  { id: 'done', title: 'Done', color: '#42b883', cards: shallowRef(makeCards('DN', perColumn, 4)) },
];
